use super::*;
#[test]
fn original_work_action_proof_preserves_the_actual_issuer_scope_and_observed_work(){let fixture:serde_json::Value=serde_json::from_str(include_str!("cases.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let mut scope=OriginalWorkScope::new();let replacement=OriginalWorkScope::new();let mut issuer=OriginalWorkActionIssuer::new();let other=OriginalWorkActionIssuer::new();let reservation=issuer.issue(&mut scope,row["reserved"].as_u64().unwrap()).unwrap();assert!(scope.has_live_actions());let mut proof=None;let admitted=issuer.commit(&mut scope,reservation,u128::from(row["actual"].as_u64().unwrap()),&mut proof).map_err(|(error,_)|error).unwrap();assert_eq!(admitted,row["admitted"].as_bool().unwrap());let original=proof.as_ref().unwrap();assert_eq!(original.actual_work(),u128::from(row["actual"].as_u64().unwrap()));assert_eq!(issuer.reserved_actions(),0);assert_eq!(issuer.committed_actions(),1);let checking_scope=if row["scope"]=="replacement"{&replacement}else{&scope};let checking_issuer=if row["issuer"]=="replacement"{&other}else{&issuer};assert_eq!(checking_issuer.validates(checking_scope,original,u128::from(row["expectedActual"].as_u64().unwrap())),row["valid"].as_bool().unwrap());issuer.finish(&mut scope,&mut proof).unwrap();assert!(proof.is_none());assert!(!scope.has_live_actions());assert!(!issuer.has_live_actions());}}
#[test]
fn occupied_proof_output_returns_the_same_original_reservation(){let mut scope=OriginalWorkScope::new();let mut issuer=OriginalWorkActionIssuer::new();let first=issuer.issue(&mut scope,1).unwrap();let mut proof=None;issuer.commit(&mut scope,first,1,&mut proof).map_err(|(error,_)|error).unwrap();let identity=proof.as_ref().unwrap().action_identity();let second=issuer.issue(&mut scope,2).unwrap();let(_,second)=issuer.commit(&mut scope,second,2,&mut proof).unwrap_err();assert_eq!(proof.as_ref().unwrap().action_identity(),identity);assert_eq!(issuer.reserved_actions(),1);assert_eq!(scope.actual_work(),3);let mut second_proof=None;issuer.commit(&mut scope,second,2,&mut second_proof).map_err(|(error,_)|error).unwrap();assert_eq!(scope.actual_work(),3);issuer.finish(&mut scope,&mut second_proof).unwrap();issuer.finish(&mut scope,&mut proof).unwrap();assert!(!scope.has_live_actions());assert!(!issuer.has_live_actions());}
#[test]
fn replacement_issuer_cannot_retire_an_original_work_reservation(){let mut scope=OriginalWorkScope::new();let mut issuer=OriginalWorkActionIssuer::new();let mut replacement=OriginalWorkActionIssuer::new();let reservation=issuer.issue(&mut scope,1).unwrap();let identity=reservation.action_identity();let(_,reservation)=replacement.cancel(&mut scope,reservation).unwrap_err();assert_eq!(reservation.action_identity(),identity);assert_eq!(issuer.reserved_actions(),1);assert_eq!(replacement.reserved_actions(),0);issuer.cancel(&mut scope,reservation).map_err(|(error,_)|error).unwrap();assert!(!scope.has_live_actions());}

#[test]
fn original_work_quote_retains_only_its_actual_producer_reply_across_unwind(){
 struct Producer{written:bool,verdict:String}
 impl OriginalWorkRecipient for Producer{type Context<'turn,'source>=usize where 'source:'turn;fn validate_context<'turn,'source>(&self,source:&usize)->Result<(),ValueError> where 'source:'turn{if *source==1{Ok(())}else{Err(ValueError::invariant("foreign original Source turn"))}}fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{None}fn admits<'a,'turn,'source>(&mut self,_:&mut usize,quote:OriginalWorkQuote<'a>,_:u64,_:u64)->OriginalWorkQuoteComplete<'a> where 'source:'turn{if self.written{let result=match self.verdict.as_str(){"accepted"=>Ok(true),"denied"=>Ok(false),_=>Err(ValueError::literal(ValueRefusalKind::WorkLimit,"original producer refusal"))};let completed=quote.complete(result);std::hint::black_box(&completed);panic!("original producer interrupted after writing")}panic!("original producer interrupted before writing")}fn settle_partial<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{let result=self.validate_context(context);check.complete(result)}fn recover_partial<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{check.pending()}}
 let fixture:serde_json::Value=serde_json::from_str(include_str!("quote.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let mut scope=OriginalWorkScope::new();let mut authority=OriginalWorkAuthority::new(Producer{written:row["written"].as_bool().unwrap(),verdict:row["verdict"].as_str().unwrap().to_owned()});let mut other=OriginalWorkAuthority::new(Producer{written:false,verdict:String::new()});let mut action=authority.with_loan(&mut 1,|loan|loan.issue(&mut scope,1)).unwrap().unwrap();let identity=action.action_identity();authority=match authority.into_recipient(){Err(authority)=>authority,Ok(_)=>panic!("live original action released its producer")};assert!(authority.with_loan(&mut 2,|_|()).is_err());let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||authority.with_loan(&mut 1,|loan|loan.admits(&scope,&mut action,0,1))));assert!(interrupted.is_err());assert_eq!(scope.actual_work(),0);assert_eq!(action.action_identity(),identity);assert!(other.with_loan(&mut 1,|loan|loan.recover(&scope,&mut action)).unwrap().is_err());let recovered=authority.with_loan(&mut 1,|loan|loan.recover(&scope,&mut action)).unwrap().unwrap();match row["recovered"].as_str().unwrap(){"pending"=>assert!(recovered.is_none()),"accepted"=>assert_eq!(recovered.unwrap().unwrap(),true),"denied"=>assert_eq!(recovered.unwrap().unwrap(),false),_=>assert_eq!(recovered.unwrap().unwrap_err().kind,ValueRefusalKind::WorkLimit)}if row["written"].as_bool().unwrap(){assert!(authority.with_loan(&mut 1,|loan|loan.recover(&scope,&mut action)).unwrap().is_err())}authority.with_loan(&mut 1,|loan|loan.cancel(&mut scope,action)).unwrap().map_err(|(error,_)|error).unwrap();assert!(!authority.has_live_actions());assert!(!scope.has_live_actions());}
}

#[test]
fn original_work_operation_binds_birth_action_before_reply_and_keeps_its_committed_proof(){
 struct Producer{written:bool,verdict:String,calls:usize}
 impl OriginalWorkRecipient for Producer{type Context<'turn,'source>=usize where 'source:'turn;fn validate_context<'turn,'source>(&self,source:&usize)->Result<(),ValueError> where 'source:'turn{if *source==1{Ok(())}else{Err(ValueError::invariant("foreign original Source turn"))}}fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{None}fn admits<'a,'turn,'source>(&mut self,_:&mut usize,quote:OriginalWorkQuote<'a>,_:u64,_:u64)->OriginalWorkQuoteComplete<'a> where 'source:'turn{self.calls+=1;if self.written{let result=match self.verdict.as_str(){"accepted"=>Ok(true),"denied"=>Ok(false),_=>Err(ValueError::literal(ValueRefusalKind::WorkLimit,"original producer refusal"))};let completed=quote.complete(result);std::hint::black_box(&completed);panic!("original producer interrupted after writing")}panic!("original producer interrupted before writing")}fn settle_partial<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{let result=self.validate_context(context);check.complete(result)}fn recover_partial<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{check.pending()}}
 let fixture:serde_json::Value=serde_json::from_str(include_str!("quote.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){
  let mut authority=OriginalWorkAuthority::new(Producer{written:row["written"].as_bool().unwrap(),verdict:row["verdict"].as_str().unwrap().to_owned(),calls:0});let mut other=OriginalWorkActionIssuer::new();let mut other_scope=OriginalWorkScope::new();let other_action=other.issue(&mut other_scope,1).unwrap();let mut foreign=Some(other_action.action_identity());let mut binding=None;let mut proof=None;
  authority.with_loan(&mut 1,|loan|{let mut scoped=loan.reborrow();let mut work=OriginalWork{state:OriginalWorkState::fresh(),recipient:Some(&mut scoped)};
   assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||work.prepare_for_action(1,&mut binding))).is_err());let identity=binding.unwrap();assert_eq!(work.state.action_identity(),Some(identity));assert!(work.quote_pending());assert_eq!(work.actual(),0);assert!(work.prepare_for_action(1,&mut None).is_err());assert!(work.prepare_for_action(1,&mut foreign).is_err());assert_eq!(binding,Some(identity));
   let recovered=work.prepare_for_action(1,&mut binding);match row["recovered"].as_str().unwrap(){
    "pending"=>{assert_eq!(recovered.unwrap(),None);assert_eq!(binding,Some(identity));work.cancel_for_action(&mut binding).unwrap()},
    "accepted"=>{assert_eq!(recovered.unwrap(),Some(true));work.commit_for_action(1,binding,&mut proof).unwrap();assert_eq!(work.actual(),1);assert!(work.has_live_actions());assert!(work.state.action_identity().is_none());assert!(work.finish_for_action(&mut proof,&mut foreign).is_err());assert_eq!(proof.as_ref().unwrap().action_identity(),identity);assert_eq!(binding,Some(identity));work.finish_for_action(&mut proof,&mut binding).unwrap()},
    "denied"=>assert_eq!(recovered.unwrap(),Some(false)),
    _=>assert_eq!(recovered.unwrap_err().kind,ValueRefusalKind::WorkLimit),
   }
   assert!(binding.is_none());assert!(proof.is_none());assert!(!work.has_live_actions());
  }).unwrap();
  assert_eq!(authority.inspect(|producer|producer.calls),1);assert!(!authority.has_live_actions());other.cancel(&mut other_scope,other_action).map_err(|(error,_)|error).unwrap();
 }
}

#[test]
fn original_work_revalidates_the_same_borrowed_turn_before_callback(){
 use std::sync::atomic::{AtomicUsize,Ordering};
 struct Producer{calls:usize}
 impl OriginalWorkRecipient for Producer{type Context<'turn,'source>=&'turn AtomicUsize where 'source:'turn;fn validate_context<'turn,'source>(&self,source:&Self::Context<'turn,'source>)->Result<(),ValueError> where 'source:'turn{if source.compare_exchange(4,3,Ordering::SeqCst,Ordering::SeqCst).is_ok(){return Ok(())}if source.load(Ordering::SeqCst)==3{panic!("original validation interrupted")}if source.load(Ordering::SeqCst)==1{Ok(())}else{Err(ValueError::invariant("original turn changed"))}}fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{None}fn admits<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,quote:OriginalWorkQuote<'reply>,_:u64,_:u64)->OriginalWorkQuoteComplete<'reply> where 'source:'turn{self.calls+=1;quote.complete(Ok(true))}fn settle_partial<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{let result=self.validate_context(context);check.complete(result)}fn recover_partial<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{check.pending()}}
 let source=AtomicUsize::new(1);let mut context=&source;let mut scope=OriginalWorkScope::new();let mut authority=OriginalWorkAuthority::new(Producer{calls:0});let mut action=authority.with_loan(&mut context,|loan|{let mut action=loan.issue(&mut scope,1).unwrap();source.store(2,Ordering::SeqCst);let error=loan.admits(&scope,&mut action,0,1).unwrap_err();assert_eq!(error.message.as_ref(),"original turn changed");action}).unwrap();assert_eq!(authority.inspect(|producer|producer.calls),0);source.store(1,Ordering::SeqCst);authority.with_loan(&mut context,|loan|loan.cancel(&mut scope,action)).unwrap().map_err(|(error,_)|error).unwrap();authority.with_loan(&mut context,|loan|{let mut action=loan.issue(&mut scope,1).unwrap();source.store(3,Ordering::SeqCst);assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||loan.admits(&scope,&mut action,0,1))).is_err());source.store(1,Ordering::SeqCst);assert!(loan.admits(&scope,&mut action,0,1).unwrap());loan.cancel(&mut scope,action).map_err(|(error,_)|error).unwrap();}).unwrap();authority.with_loan(&mut context,|loan|{let mut action=loan.issue(&mut scope,1).unwrap();source.store(4,Ordering::SeqCst);assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||loan.admits(&scope,&mut action,0,1))).is_err());source.store(1,Ordering::SeqCst);assert_eq!(loan.recover(&scope,&mut action).unwrap().unwrap().unwrap(),true);loan.cancel(&mut scope,action).map_err(|(error,_)|error).unwrap();}).unwrap();assert_eq!(authority.inspect(|producer|producer.calls),2);assert!(!authority.has_live_actions());
}

#[test]
fn original_work_action_rejects_a_different_actual_dispatch_of_the_same_source(){
 struct Producer{source:crate::OriginalSourceTurnIssuer}
 impl OriginalWorkRecipient for Producer{type Context<'turn,'source>=&'turn crate::OriginalSourceTurn where 'source:'turn;fn validate_context<'turn,'source>(&self,turn:&Self::Context<'turn,'source>)->Result<(),ValueError> where 'source:'turn{self.source.validate(turn).map_err(Into::into)}fn source_turn<'turn,'source>(&self,turn:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{Some(turn.identity())}fn admits<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,quote:OriginalWorkQuote<'reply>,_:u64,_:u64)->OriginalWorkQuoteComplete<'reply> where 'source:'turn{quote.complete(Ok(true))}fn settle_partial<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{let result=self.validate_context(context);check.complete(result)}fn recover_partial<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{check.pending()}}
 let source=crate::OriginalSourceTurnIssuer::new();let first=source.issue().unwrap();let second=source.issue().unwrap();let mut authority=OriginalWorkAuthority::new(Producer{source});let mut scope=OriginalWorkScope::new();let mut first_context=&first;let mut action=authority.with_loan(&mut first_context,|loan|{let mut action=loan.issue(&mut scope,1).unwrap();assert!(loan.admits(&scope,&mut action,0,1).unwrap());action}).unwrap();let identity=action.action_identity();let mut second_context=&second;action=match authority.with_loan(&mut second_context,|loan|loan.cancel(&mut scope,action)).unwrap(){Err((error,action))=>{assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);action},Ok(())=>panic!("different Source dispatch canceled original work")};assert_eq!(action.action_identity(),identity);authority.with_loan(&mut first_context,|loan|loan.cancel(&mut scope,action)).unwrap().map_err(|(error,_)|error).unwrap();assert!(!authority.has_live_actions());
}
#[test]
fn original_work_partial_turns_invoice_once_and_keep_original_ceiling(){
 struct Producer;
 impl OriginalWorkRecipient for Producer{type Context<'turn,'source>=() where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError> where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{None}fn admits<'reply,'turn,'source>(&mut self,_:&mut (),reply:OriginalWorkQuote<'reply>,_:u64,_:u64)->OriginalWorkQuoteComplete<'reply> where 'source:'turn{reply.complete(Ok(true))}fn settle_partial<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{let result=self.validate_context(context);check.complete(result)}fn recover_partial<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{check.pending()}}
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../🎟️work-action/🧪️tests/partial.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let mut authority=OriginalWorkAuthority::new(Producer);let mut state=OriginalWorkState::fresh();let mut action=None;let mut proof=None;let reserved=row["reserved"].as_u64().unwrap();authority.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork{state:state.take(),recipient:Some(&mut loan)};assert_eq!(work.prepare_for_action(reserved,&mut action).unwrap(),Some(true));state=work.state.take()}).unwrap();let identity=action.unwrap();let mut paid=0;let mut previous_receipt=None;for value in row["partials"].as_array().unwrap(){let delta=value.as_u64().unwrap();authority.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();state.begin_turn();let mut work=OriginalWork{state:state.take(),recipient:Some(&mut loan)};let mut performed=None;work.issue_performed_for_action(action,&mut performed).unwrap();let receipt_identity=performed.as_ref().unwrap().identity();if let Some(previous)=previous_receipt{assert_ne!(previous,receipt_identity)}previous_receipt=Some(receipt_identity);let admitted=OriginalWorkSink::performed(performed.as_mut().unwrap(),delta).unwrap();work.claim_performed_for_action(action,&mut performed).unwrap();paid+=delta;let mut partial_output=None;assert!(work.settle_partial_for_action_into(action,&mut partial_output).unwrap());let receipt=partial_output.take().unwrap();assert_eq!(receipt.identity(),receipt_identity);assert_eq!((receipt.delta(),receipt.total(),receipt.admitted(),receipt.source_refusal().is_none()),(u128::from(delta),u128::from(paid),paid<=reserved,true));assert_eq!(admitted,paid<=reserved);assert_eq!(work.actual(),u128::from(paid));assert_eq!(work.state.action_identity(),Some(identity));state=work.state.take()}).unwrap()}
  authority.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();state.begin_turn();let mut work=OriginalWork{state:state.take(),recipient:Some(&mut loan)};let final_work=row["final"].as_u64().unwrap();let result=work.commit_for_action(u128::from(final_work),action,&mut proof);if row["valid"].as_bool().unwrap(){assert_eq!(result.unwrap(),row["expectedAdmitted"].as_bool().unwrap());assert_eq!(work.actual(),u128::from(row["expectedActual"].as_u64().unwrap()));assert_eq!(proof.as_ref().unwrap().actual_work(),u128::from(final_work));work.finish_for_action(&mut proof,&mut action).unwrap()}else{assert!(result.is_err());assert_eq!(work.actual(),u128::from(paid));assert_eq!(work.state.action_identity(),Some(identity));assert_eq!(work.commit_for_action(u128::from(paid),action,&mut proof).unwrap(),paid<=reserved);work.finish_for_action(&mut proof,&mut action).unwrap()}state=work.state.take()}).unwrap();assert!(action.is_none()&&proof.is_none()&&!authority.has_live_actions());drop(state);
 }
}
#[test]
fn performed_receipt_preserves_real_source_refusal_across_unwind(){
 struct Producer{error:Option<ValueError>,calls:usize}
 impl OriginalWorkRecipient for Producer{
  type Context<'a,'b>=() where 'b:'a;
  fn validate_context<'a,'b>(&self,_:&())->Result<(),ValueError> where 'b:'a{Ok(())}
  fn source_turn<'a,'b>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity> where 'b:'a{None}
  fn admits<'r,'a,'b>(&mut self,_:&mut (),quote:OriginalWorkQuote<'r>,_:u64,_:u64)->OriginalWorkQuoteComplete<'r> where 'b:'a{quote.complete(Ok(true))}
  fn settle_partial<'r,'a,'b>(&mut self,_:&mut (),check:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r> where 'b:'a{self.calls+=1;assert_eq!((check.delta(),check.total()),(2,2));let _done=check.complete(Err(self.error.take().unwrap()));panic!("actual Source refusal interrupted after reply")}
  fn recover_partial<'r,'a,'b>(&mut self,_:&mut (),check:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r> where 'b:'a{check.pending()}
 }
 let error=ValueError::new(ValueRefusalKind::Canceled,"actual partial Source refusal".to_owned());let pointer=error.message.as_ptr();let mut authority=OriginalWorkAuthority::new(Producer{error:Some(error),calls:0});let(mut action,mut performed,mut proof)=(None,None,None);authority.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut performed).unwrap();assert!(work.performed_total_for_action(action).is_err());{let mut actual=None;let mut effect=crate::RetainedAllocationEffect::new(crate::RetainedCloneGrant::default(),1,&mut actual,performed.as_mut().unwrap());for i in 0u64..2{std::hint::black_box(i.wrapping_add(1));let admitted=effect.performed(1).unwrap();assert_eq!(admitted,i==0)}assert_eq!(effect.performed_work(),2)}work.claim_performed_for_action(action,&mut performed).unwrap();assert_eq!(work.performed_total_for_action(action).unwrap(),2);assert!(work.partial_pending_for_action(action).unwrap());assert_eq!(work.actual(),2);let mut output=None;assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||work.settle_partial_for_action_into(action,&mut output))).is_err());assert!(output.is_none());assert_eq!(work.actual(),2);assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{assert!(work.settle_partial_for_action_into(action,&mut output).unwrap());panic!("wrapper interrupted after resident outcome")})).is_err());assert!(work.settle_partial_for_action_into(action,&mut output).is_err());let receipt=output.take().unwrap();assert!(!work.partial_pending_for_action(action).unwrap());assert_eq!((receipt.delta(),receipt.total(),receipt.admitted()),(2,2,false));assert_eq!(receipt.source_refusal().unwrap().message.as_ptr(),pointer);assert!(!work.commit_for_action(2,action,&mut proof).unwrap());assert_eq!(work.actual(),2);work.finish_for_action(&mut proof,&mut action).unwrap();drop(receipt)}).unwrap();assert_eq!(authority.inspect(|p|p.calls),1);assert!(!authority.has_live_actions());
}
#[test]
fn performed_work_keeps_source_context_refusal_independent(){
 use std::sync::atomic::{AtomicBool,Ordering};
 struct Producer;
 impl OriginalWorkRecipient for Producer{type Context<'a,'b>=&'a AtomicBool where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.load(Ordering::Relaxed){Ok(())}else{Err(ValueError::new(ValueRefusalKind::Canceled,"actual changed Source context".to_owned()))}}fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<crate::OriginalSourceTurnIdentity> where 'b:'a{None}fn admits<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,quote:OriginalWorkQuote<'r>,_:u64,_:u64)->OriginalWorkQuoteComplete<'r> where 'b:'a{quote.complete(Ok(true))}fn settle_partial<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,check:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r> where 'b:'a{check.complete(self.validate_context(c))}fn recover_partial<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,check:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r> where 'b:'a{check.pending()}}
 let valid=AtomicBool::new(true);let mut context=&valid;let mut authority=OriginalWorkAuthority::new(Producer);let(mut action,mut receipt,mut proof)=(None,None,None);authority.with_loan(&mut context,|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));valid.store(false,Ordering::Relaxed);let entry_error=work.validate_action_source(action).unwrap_err();assert!(receipt.is_none());assert_eq!(work.actual(),0);valid.store(true,Ordering::Relaxed);work.validate_action_source(action).unwrap();drop(entry_error);work.issue_performed_for_action(action,&mut receipt).unwrap();std::hint::black_box(1u64.wrapping_add(1));assert!(OriginalWorkSink::performed(receipt.as_mut().unwrap(),1).unwrap());work.claim_performed_for_action(action,&mut receipt).unwrap();valid.store(false,Ordering::Relaxed);let mut partial_output=None;let error=work.settle_partial_for_action_into(action,&mut partial_output).unwrap_err();let pointer=error.message.as_ptr();assert_eq!(work.actual(),1);assert!(work.partial_pending_for_action(action).unwrap());valid.store(true,Ordering::Relaxed);assert!(work.settle_partial_for_action_into(action,&mut partial_output).unwrap());let settled=partial_output.take().unwrap();assert_eq!((settled.delta(),settled.total(),settled.admitted()),(1,1,true));assert!(settled.source_refusal().is_none());assert_eq!(error.message.as_ptr(),pointer);assert!(work.commit_for_action(1,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap();drop(error)}).unwrap();assert!(!authority.has_live_actions());
}
